
		if(typeof $ === 'undefined' && typeof jQuery !== 'undefined'){window.$ = jQuery;}
		var config = window.contactinbox_admin || {};
		// Subject field enable/disable button AJAX logic
		var $subjectBtn = $('#form-enable-subject-btn');
		var $subjectHidden = $('#form-enable-subject-hidden');
		var $subjectStatus = $('#contactin-subject-status-label');
		if ($subjectBtn.length && $subjectHidden.length && $subjectStatus.length) {
			$subjectBtn.off('click').on('click', function () {
				var enabled = $subjectBtn.data('enabled') === 1 || $subjectBtn.data('enabled') === '1';
				var newEnabled = !enabled;
				$subjectBtn.prop('disabled', true).text('Saving...');
				$.post({
					url: config.ajaxurl,
					data: {
						action: 'contactin_toggle_subject',
						enabled: newEnabled ? '1' : '0',
						nonce: config.nonce_save
					},
					dataType: 'json'
				}).done(function (response) {
					if (response && response.success) {
						$subjectBtn.data('enabled', newEnabled ? 1 : 0)
							.toggleClass('enabled', newEnabled)
							.text(newEnabled ? 'Disable Subject Field' : 'Enable Subject Field');
						$subjectHidden.val(newEnabled ? '1' : '0');
						$subjectStatus.text(newEnabled ? 'Enabled' : 'Disabled')
							.removeClass('enabled disabled')
							.addClass(newEnabled ? 'enabled' : 'disabled');
					} else {
						$subjectBtn.text('Error');
						$subjectStatus.text('Error')
							.removeClass('enabled disabled')
							.addClass('disabled');
					}
				}).fail(function () {
					$subjectBtn.text('Error');
					$subjectStatus.text('Error')
						.removeClass('enabled')
						.addClass('disabled');
				}).always(function () {
					setTimeout(function () {
						var enabled = $subjectBtn.data('enabled') === 1 || $subjectBtn.data('enabled') === '1';
						$subjectBtn.prop('disabled', false).text(enabled ? 'Disable Subject Field' : 'Enable Subject Field');
						$subjectStatus.text(enabled ? 'Enabled' : 'Disabled')
							.removeClass('enabled disabled')
							.addClass(enabled ? 'enabled' : 'disabled');
					}, 1200);
				});
			});
		}

		// File Attachment enable/disable button AJAX logic with REST API dependency logic
		var $attachmentBtn = $('#form-enable-attachment-btn');
		var $attachmentHidden = $('#form-enable-attachment-hidden');
		var $attachmentStatus = $('#contactin-attachment-status-label');
		var $restApiHidden = $("input[name='restapi_enable']");
		var attachmentRestApiModal = document.getElementById('contactin-attachment-restapi-modal');
		var attachmentRestApiConfirm = document.getElementById('contactin-attachment-restapi-confirm');
		var attachmentRestApiCancel = document.getElementById('contactin-attachment-restapi-cancel');
		var attachmentRestApiDisableModal = document.getElementById('contactin-attachment-restapi-disable-modal');
		var attachmentRestApiDisableConfirm = document.getElementById('contactin-attachment-restapi-disable-confirm');
		var attachmentRestApiDisableCancel = document.getElementById('contactin-attachment-restapi-disable-cancel');
		var pendingEnableAttachment = null;
		var restApiEnabledViaAttachment = false;
		var restApiDisabledWithAttachment = false;
		var restApiStateBeforeToggle = null;
		function cinBindModal(modal) {
			if (!modal || modal.dataset.cinBound === '1') return;
			modal.dataset.cinBound = '1';
			modal.setAttribute('role', 'dialog');
			modal.setAttribute('aria-modal', 'true');
			var overlay = modal.querySelector('.cin-modal-overlay');
			var closeButtons = modal.querySelectorAll('.cin-modal-close');
			closeButtons.forEach(function(btn) {
				btn.addEventListener('click', function(e) {
					if (e && typeof e.preventDefault === 'function') e.preventDefault();
					cinCloseModal(modal);
				});
			});
			if (overlay) {
				overlay.addEventListener('click', function() { cinCloseModal(modal); });
			}
			modal.addEventListener('keydown', function(e) {
				if (e.key === 'Escape') {
					cinCloseModal(modal);
				}
			});
		}
		function cinOpenModal(modal, trigger) {
			if (!modal) return;
			cinBindModal(modal);
			modal.classList.remove('cin-modal-hidden');
			modal.setAttribute('aria-hidden', 'false');
			if (trigger && trigger.focus) {
				modal.dataset.cinTrigger = trigger;
			}
		}
		function cinCloseModal(modal) {
			if (!modal) return;
			modal.classList.add('cin-modal-hidden');
			modal.setAttribute('aria-hidden', 'true');
		}
		function notifyAttachment(msg, type) {
			if (typeof window.cinShowMessage === 'function') {
				window.cinShowMessage(msg, type || 'info', 5000);
			} else {
				window.alert(msg);
			}
		}
		if ($attachmentBtn.length && $attachmentHidden.length && $attachmentStatus.length) {
			$attachmentBtn.off('click').on('click', function () {
				restApiStateBeforeToggle = $restApiHidden.length && ($restApiHidden.val() === '1' || $restApiHidden.val() === 1);
				var enabled = $attachmentBtn.data('enabled') === 1 || $attachmentBtn.data('enabled') === '1';
				var newEnabled = !enabled;
				// If enabling file upload and REST API is disabled, prompt user and enable both on confirm
				if (newEnabled && $restApiHidden.length && ($restApiHidden.val() === '0' || $restApiHidden.val() === 0)) {
					if (attachmentRestApiModal) {
						cinBindModal(attachmentRestApiModal);
						var cleanup = function() {
							if (attachmentRestApiConfirm) attachmentRestApiConfirm.removeEventListener('click', onConfirm);
							if (attachmentRestApiCancel) attachmentRestApiCancel.removeEventListener('click', onCancel);
							attachmentRestApiModal.querySelectorAll('.cin-modal-close').forEach(function(btn){ btn.removeEventListener('click', onCancel); });
							var overlay = attachmentRestApiModal.querySelector('.cin-modal-overlay');
							if (overlay) overlay.removeEventListener('click', onCancel);
							pendingEnableAttachment = null;
						};
						var onCancel = function(event) {
							if (event && typeof event.preventDefault === 'function') event.preventDefault();
							cleanup();
							cinCloseModal(attachmentRestApiModal);
						};
						var onConfirm = function(event) {
							if (event && typeof event.preventDefault === 'function') event.preventDefault();
							cleanup();
							$restApiHidden.val('1');
							restApiEnabledViaAttachment = true;
							cinCloseModal(attachmentRestApiModal);
							doAttachmentToggle(newEnabled);
						};
						if (attachmentRestApiConfirm) attachmentRestApiConfirm.addEventListener('click', onConfirm);
						if (attachmentRestApiCancel) attachmentRestApiCancel.addEventListener('click', onCancel);
						attachmentRestApiModal.querySelectorAll('.cin-modal-close').forEach(function(btn){ btn.addEventListener('click', onCancel); });
						var overlay = attachmentRestApiModal.querySelector('.cin-modal-overlay');
						if (overlay) overlay.addEventListener('click', onCancel);
						pendingEnableAttachment = newEnabled;
						cinOpenModal(attachmentRestApiModal, $attachmentBtn[0]);
						return;
					}
					$restApiHidden.val('1');
					restApiEnabledViaAttachment = true;
				}
				// If disabling file upload and REST API is enabled, show modal to decide REST API state
				if (!newEnabled && $restApiHidden.length && ($restApiHidden.val() === '1' || $restApiHidden.val() === 1)) {
					if (attachmentRestApiDisableModal) {
						cinBindModal(attachmentRestApiDisableModal);
						var cleanupDisable = function() {
							if (attachmentRestApiDisableConfirm) attachmentRestApiDisableConfirm.removeEventListener('click', onDisableConfirm);
							if (attachmentRestApiDisableCancel) attachmentRestApiDisableCancel.removeEventListener('click', onDisableCancel);
							attachmentRestApiDisableModal.querySelectorAll('.cin-modal-close').forEach(function(btn){ btn.removeEventListener('click', onDisableCancel); });
							var overlay = attachmentRestApiDisableModal.querySelector('.cin-modal-overlay');
							if (overlay) overlay.removeEventListener('click', onDisableCancel);
						};
						var onDisableCancel = function(event) {
							if (event && typeof event.preventDefault === 'function') event.preventDefault();
							cleanupDisable();
							cinCloseModal(attachmentRestApiDisableModal);
							doAttachmentToggle(newEnabled);
						};
						var onDisableConfirm = function(event) {
							if (event && typeof event.preventDefault === 'function') event.preventDefault();
							cleanupDisable();
							$restApiHidden.val('0');
							restApiDisabledWithAttachment = true;
							cinCloseModal(attachmentRestApiDisableModal);
							doAttachmentToggle(newEnabled);
						};
						if (attachmentRestApiDisableConfirm) attachmentRestApiDisableConfirm.addEventListener('click', onDisableConfirm);
						if (attachmentRestApiDisableCancel) attachmentRestApiDisableCancel.addEventListener('click', onDisableCancel);
						attachmentRestApiDisableModal.querySelectorAll('.cin-modal-close').forEach(function(btn){ btn.addEventListener('click', onDisableCancel); });
						var overlay = attachmentRestApiDisableModal.querySelector('.cin-modal-overlay');
						if (overlay) overlay.addEventListener('click', onDisableCancel);
						cinOpenModal(attachmentRestApiDisableModal, $attachmentBtn[0]);
						return;
					}
					// Fallback to original popup
					showRestApiDisablePopup(function(leaveEnabled) {
						if (!leaveEnabled) {
							$restApiHidden.val('0');
							restApiDisabledWithAttachment = true;
						}
						doAttachmentToggle(newEnabled);
					});
					return;
				}
				doAttachmentToggle(newEnabled);
			});
		}

		function doAttachmentToggle(newEnabled) {
			$attachmentBtn.prop('disabled', true).text('Saving...');
			$.post({
				url: config.ajaxurl,
				data: {
					action: 'contactin_toggle_attachment',
					enabled: newEnabled ? '1' : '0',
					nonce: config.nonce_save
				},
				dataType: 'json'
			}).done(function (response) {
				if (response && response.success) {
					$attachmentBtn.data('enabled', newEnabled ? 1 : 0)
						.toggleClass('enabled', newEnabled)
						.text(newEnabled ? 'Disable File Attachment' : 'Enable File Attachment');
					$attachmentHidden.val(newEnabled ? '1' : '0');
					$attachmentStatus.text(newEnabled ? 'Enabled' : 'Disabled')
						.removeClass('enabled disabled')
						.addClass(newEnabled ? 'enabled' : 'disabled');
					if (newEnabled) {
						if (restApiEnabledViaAttachment) {
							notifyAttachment('File attachment enabled. REST API was enabled to support uploads.', 'success');
						} else if (restApiStateBeforeToggle) {
							notifyAttachment('File attachment enabled. REST API was already enabled.', 'success');
						} else {
							notifyAttachment('File attachment enabled.', 'success');
						}
					} else {
						if (restApiDisabledWithAttachment) {
							notifyAttachment('File attachment disabled. REST API disabled as well.', 'info');
						} else if (restApiStateBeforeToggle) {
							notifyAttachment('File attachment disabled. REST API remains enabled.', 'info');
						} else {
							notifyAttachment('File attachment disabled.', 'info');
						}
					}
				} else {
					$attachmentBtn.text('Error');
					$attachmentStatus.text('Error')
						.removeClass('enabled disabled')
						.addClass('disabled');
				}
			}).fail(function () {
				$attachmentBtn.text('Error');
				$attachmentStatus.text('Error')
					.removeClass('enabled')
					.addClass('disabled');
			}).always(function () {
				restApiEnabledViaAttachment = false;
				restApiDisabledWithAttachment = false;
				restApiStateBeforeToggle = null;
				setTimeout(function () {
					var enabled = $attachmentBtn.data('enabled') === 1 || $attachmentBtn.data('enabled') === '1';
					$attachmentBtn.prop('disabled', false).text(enabled ? 'Disable File Attachment' : 'Enable File Attachment');
					$attachmentStatus.text(enabled ? 'Enabled' : 'Disabled')
						.removeClass('enabled disabled')
						.addClass(enabled ? 'enabled' : 'disabled');
				}, 1200);
			});
		}

		function showRestApiDisablePopup(callback) {
			var dialog = $('<div class="cin-modal-dialog" style="z-index:99999;position:fixed;top:0;left:0;width:100vw;height:100vh;background:rgba(0,0,0,0.25);display:flex;align-items:center;justify-content:center;"><div style="background:#fff;padding:32px 28px 24px 28px;border-radius:10px;box-shadow:0 8px 32px rgba(0,0,0,0.18);max-width:420px;width:90vw;text-align:center;"><div style="font-size:17px;font-weight:600;margin-bottom:18px;">REST API is currently enabled. Some integrations or apps may rely on it.<br><br><span style=\"font-weight:400;font-size:15px;\">Would you like to keep REST API enabled after disabling file upload?</span></div><div style="margin-top:18px;display:flex;gap:18px;justify-content:center;"><button class="button button-primary cin-modal-yes" style="min-width:70px;">Yes, keep enabled</button><button class="button button-secondary cin-modal-no" style="min-width:70px;">No, disable REST API</button></div></div></div>');
			$(document.body).append(dialog);
			dialog.find('.cin-modal-yes').on('click', function () {
				dialog.remove();
				if (typeof callback === 'function') callback(true);
			});
			dialog.find('.cin-modal-no').on('click', function () {
				dialog.remove();
				if (typeof callback === 'function') callback(false);
			});
		}
/**
 * ContactIn – Admin Settings
 */
(function ($) {
	'use strict';

	if (!window.contactinbox_admin) {
		return;
	}

	const config = window.contactinbox_admin;
	let submitHandler = null;

	function initSettings() {
		const $form = $('#contactin-settings-form');
		if (!$form.length) {
			// console.error('[CONFETTI] Form #contactin-settings-form NOT FOUND!');
			setTimeout(initSettings, 100);
			return;
		}

		// console.log('[CONFETTI] Form FOUND - initializing');

		// Unbind previous handler if it exists to avoid duplicates
		if (submitHandler) {
			$form.off('submit', submitHandler);
		}

		const $submit = $form.find('button[type="submit"], input[type="submit"]');
		const $spinner = $form.find('.spinner');
		const $notice = $form.find('.contactin-saved');

		// Ensure button is enabled when form loads
		$submit.prop('disabled', false).removeClass('cin-saving cin-saved cin-error');
		$spinner.removeClass('is-active');
		$notice.hide().removeClass('cin-success cin-error');

		// Get confetti checkbox for later use
		const $confettiCheckbox = $form.find('#confetti-enable-checkbox');
		
		// console.log('[CONFETTI] Checkbox found:', $confettiCheckbox.length, 'element:', $confettiCheckbox[0]);
		// console.log('[CONFETTI] Checkbox checked state:', $confettiCheckbox.prop('checked'));
		// console.log('[CONFETTI] Checkbox parent:', $confettiCheckbox.parent()[0]);
		
		// Ensure confetti checkbox is always enabled
		if ($confettiCheckbox.length) {
			$confettiCheckbox.prop('disabled', false).prop('readonly', false).removeAttr('disabled');
			
			// Simple change handler to sync hidden field
			$confettiCheckbox.off('change').on('change', function() {
				// console.log('[CONFETTI] Change event fired - checked:', this.checked);
				const hiddenField = $form.find('input[type="hidden"][name="confetti_enable"]');
				if (hiddenField.length) {
					hiddenField.val(this.checked ? '1' : '0');
					// console.log('[CONFETTI] Hidden field synced to:', this.checked ? '1' : '0');
				}
			});

			// Test click handler
			$confettiCheckbox.on('click', function() {
				// console.log('[CONFETTI] Click detected!');
			});
		}

		// Create submit handler
		submitHandler = function (e) {
			e.preventDefault();

			// Check if already submitting
			if ($submit.prop('disabled')) {
				return;
			}

			// Visual state: Saving
			$spinner.addClass('is-active');
			$submit.prop('disabled', true).addClass('cin-saving').text('Saving...');
			$notice.stop().hide().removeClass('cin-success cin-error');

			// Build explicit payload
			const payload = new FormData();

			// Add hidden inputs and text fields
			$form.find('input[type="text"], input[type="url"], input[type="email"], input[type="number"], textarea, select').each(function () {
				const $el = $(this);
				const name = $el.attr('name');
				const value = $el.val();
				if (name && value !== null && value !== undefined) {
					if ($el.attr('type') === 'checkbox' || $el.attr('type') === 'radio') {
						return; // Skip, will handle separately
					}
					if (name.endsWith('[]')) {
						if ($.isArray(value)) {
							$.each(value, function (i, v) {
								payload.append(name, v);
							});
						}
					} else {
						payload.set(name, value);
					}
				}
			});

			// Add hidden fields
			$form.find('input[type="hidden"]').each(function () {
				const $el = $(this);
				const name = $el.attr('name');
				const value = $el.val();
				if (name && value) {
					payload.set(name, value);
				}
			});

			// Add checkbox states explicitly
			$form.find('input[type="checkbox"]').each(function () {
				const name = $(this).attr('name');
				if (name && !name.endsWith('[]')) {
					payload.set(name, $(this).is(':checked') ? '1' : '0');
				}
			});

			// Send AJAX
			$.ajax({
				url: config.ajaxurl,
				type: 'POST',
				data: payload,
				processData: false,
				contentType: false,
				dataType: 'json',
				timeout: 10000,
				success: function (response) {
					const success = response && response.success === true;
					const message = (response && response.data && response.data.message) || (success ? 'Settings saved successfully!' : 'Failed to save settings.');

					// Sync all form fields from response
					if (success && response.data && response.data.settings) {
						const settings = response.data.settings;
						
						// Sync checkboxes
						$form.find('input[type="checkbox"]').each(function () {
							const name = $(this).attr('name');
							if (name && settings.hasOwnProperty(name)) {
								const checked = settings[name] === true || settings[name] === 1 || settings[name] === '1';
								$(this).prop('checked', checked);
							}
						});

						// Sync text/other fields
						$form.find('input[type="text"], input[type="url"], input[type="email"], input[type="number"], textarea').each(function () {
							const name = $(this).attr('name');
							if (name && settings.hasOwnProperty(name)) {
								$(this).val(settings[name]);
							}
						});

						// Sync selects
						$form.find('select').each(function () {
							const name = $(this).attr('name');
							if (name && settings.hasOwnProperty(name)) {
								const value = settings[name];
								if (name.endsWith('[]') && $.isArray(value)) {
									$(this).val(value);
								} else if (!name.endsWith('[]')) {
									$(this).val(value);
								}
							}
						});
					}

					// Show global notice at top using WordPress notice classes
					var $globalNotice = $('#cin-global-settings-notice');
					if ($globalNotice.length) {
						// Remove old notice classes and add appropriate WordPress notice class
						$globalNotice
							.removeClass('notice-success notice-error notice-warning notice-info')
							.addClass(success ? 'notice-success' : 'notice-error')
							.addClass('is-dismissible');
						
						// Update the notice message
						$globalNotice.find('p').text(message);
						
						// Make sure the close button is visible and wired up
						var $dismiss = $globalNotice.find('.notice-dismiss, .cin-notice-dismiss');
						$dismiss.off('click').on('click', function() {
							$globalNotice.fadeOut(200);
						});
						
						// Show the notice
						$globalNotice.fadeIn(300);
						
						// Auto-hide success messages after 5 seconds
						if (success) {
							setTimeout(function() {
								$globalNotice.fadeOut(300);
							}, 5000);
						}
					} else {
						// Fallback to inline notice if global notice area doesn't exist
						const cssClass = success ? 'cin-success' : 'cin-error';
						const bgColor = success ? '#d4edda' : '#f8d7da';
						const textColor = success ? '#155724' : '#721c24';
						const borderColor = success ? '#c3e6cb' : '#f5c6cb';
						
						$notice
							.addClass(cssClass)
							.text(message)
							.css({
								'color': textColor,
								'background-color': bgColor,
								'border-left-color': borderColor,
								'padding': '12px 15px',
								'margin': '12px 0',
								'border-left': '4px solid',
								'border-radius': '4px',
								'font-weight': '500'
							})
							.fadeIn(300);
					}

					// Trigger custom event for post-save logic (e.g., REST API status message)
					$(document).trigger('cin:settings:saved', [{success, message, settings: response && response.data && response.data.settings}]);

					// Reset button state after delay
					setTimeout(function () {
						$submit.removeClass('cin-saving cin-saved cin-error').prop('disabled', false);
						if (success) {
							$notice.delay(2000).fadeOut(500);
						}
					}, 1500);
				},
				error: function (xhr, status, error) {
					let msg = 'Network error. Try again.';
					if (status === 'timeout') {
						msg = 'Request timed out. Please try again.';
					}

					// Show error in global notice area
					var $globalNotice = $('#cin-global-settings-notice');
					if ($globalNotice.length) {
						$globalNotice
							.removeClass('notice-success notice-error notice-warning notice-info')
							.addClass('notice-error is-dismissible');
						$globalNotice.find('p').text(msg);
						var $dismiss = $globalNotice.find('.notice-dismiss, .cin-notice-dismiss');
						$dismiss.off('click').on('click', function() {
							$globalNotice.fadeOut(200);
						});
						$globalNotice.fadeIn(300);
					} else {
						// Fallback to inline notice if global notice area doesn't exist
						const bgColor = '#f8d7da';
						const textColor = '#721c24';
						const borderColor = '#f5c6cb';

						$notice
							.addClass('cin-error')
							.text(msg)
							.css({
								'color': textColor,
								'background-color': bgColor,
								'border-left-color': borderColor,
								'padding': '12px 15px',
								'margin': '12px 0',
								'border-left': '4px solid',
								'border-radius': '4px',
								'font-weight': '500'
							})
							.fadeIn(300);
					}

					// Reset button
					$submit.removeClass('cin-saving cin-saved cin-error').prop('disabled', false);
				},
				complete: function () {
					$spinner.removeClass('is-active');
				}
			});
		};

		// Bind the submit handler
		$form.on('submit', submitHandler);

		// Handle confetti checkbox – ensure hidden field stays in sync
		if ($confettiCheckbox.length) {
			// Already handled in the change event above
		}

		// Handle SMTP test button
		const $smtpBtn = $('#contactin-test-smtp');
		if ($smtpBtn.length) {
			$smtpBtn.off('click').on('click', function (e) {
				e.preventDefault();

				if ($(this).prop('disabled')) {
					return;
				}

				const $btn = $(this);
				const $spinner = $btn.find('.spinner');
				const $result = $('#contactin-smtp-result');
				const origText = $btn.text();
				const $btnLabel = $btn.find('.btn-text');

				// Visual state: Testing
				$btn.prop('disabled', true).addClass('button-loading');
				if ($btnLabel.length) {
					$btnLabel.text('Testing SMTP...');
				} else {
					$btn.text('Testing SMTP...');
				}
				$spinner.addClass('is-active');
				$result.stop().fadeOut(150);

				$.ajax({
					url: config.ajaxurl,
					type: 'POST',
					data: {
						action: 'ci_test_smtp',
						nonce: config.nonce_smtp,
						host: $('#smtp_host').val(),
						port: $('#smtp_port').val(),
						username: $('#smtp_user').val(),
						password: $('#smtp_pass').val(),
						enc: $('#smtp_encryption').val(),
						to: $('#admin_email').val(),
						smtp_from_email: $('#smtp_from_email').val(),
						smtp_from_name: $('#smtp_from_name').val()
					},
					dataType: 'json',
					timeout: 15000
				}).done(function (response) {
					const success = response && response.success === true;
					const message = (response && response.data && response.data.message) || (success ? 'SMTP test email sent successfully!' : 'SMTP test failed.');
					const bgColor = success ? '#d4edda' : '#f8d7da';
					const textColor = success ? '#155724' : '#721c24';
					const borderColor = success ? '#c3e6cb' : '#f5c6cb';

					if (success) {
						$btn.addClass('button-success').removeClass('button-error');
						if ($btnLabel.length) {
							$btnLabel.text('Success!');
						} else {
							$btn.text('Success!');
						}
					} else {
						$btn.addClass('button-error').removeClass('button-success');
						if ($btnLabel.length) {
							$btnLabel.text('Failed');
						} else {
							$btn.text('Failed');
						}
					}

					$result
						.html('<span style="color: ' + textColor + '; background-color: ' + bgColor + '; border-left: 4px solid ' + borderColor + '; padding: 10px 12px; margin: 8px 0; border-radius: 3px; display: block; font-weight: 500;">' + message + '</span>')
						.fadeIn(300);
				}).fail(function (xhr, status, error) {
					const message = status === 'timeout' ? 'SMTP test timed out. Check your settings.' : 'Connection failed. Try again.';
					const bgColor = '#f8d7da';
					const textColor = '#721c24';
					const borderColor = '#f5c6cb';

					$btn.addClass('button-error').removeClass('button-success');
					if ($btnLabel.length) {
						$btnLabel.text('Failed');
					} else {
						$btn.text('Failed');
					}

					$result
						.html('<span style="color: ' + textColor + '; background-color: ' + bgColor + '; border-left: 4px solid ' + borderColor + '; padding: 10px 12px; margin: 8px 0; border-radius: 3px; display: block; font-weight: 500;">' + message + '</span>')
						.fadeIn(300);
				}).always(function () {
					$spinner.removeClass('is-active');

					// Reset button after 4 seconds
					setTimeout(function () {
						$btn.prop('disabled', false).removeClass('button-loading button-success button-error');
						if ($btnLabel.length) {
							$btnLabel.text(origText);
						} else {
							$btn.text(origText);
						}
					}, 4000);
				});
			});
		}
	}

	// Start initialization when DOM is ready
	if (document.readyState === 'loading') {
		$(document).ready(initSettings);
	} else {
		initSettings();
	}

})(jQuery);
